   var a=v.getAsJsonObject();require(words("user target").contains(a.get("who").getAsString()),where,"Invalid condition subject");
   if(words("ability effectiveAbility sideAbility allyAbility item sideItem lastMove").contains(k))require(a.has("values") && a.get("values").isJsonArray() && !a.getAsJsonArray("values").isEmpty(),where,"Empty ID list");
