    if(a.has("boosts")){stats(a.getAsJsonObject("boosts"),where);require(!a.has("fraction"),where,"Invalid hazard burst effect");}else require(numeric(a.get("fraction")) && a.get("fraction").getAsDouble()>0 && a.get("fraction").getAsDouble()<=1,where,"Invalid hazard burst effect");
